fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // We want to find:
    // i = smallest index where lst[i] is even,
    // j = smallest index where lst[j] is odd.
    //
    // By definition:
    // - For i, all elements before i are odd.
    // - For j, all elements before j are even.
    //
    // Because the array has at least one even and one odd, and at least length 2,
    // both i and j exist.
    
    let mut even_index: Option<usize> = None;
    let mut odd_index: Option<usize> = None;

    for (idx, &val) in lst.iter().enumerate() {
        if even_index.is_none() && val % 2 == 0 {
            // first even element
            even_index = Some(idx);
        }
        if odd_index.is_none() && val % 2 != 0 {
            // first odd element
            odd_index = Some(idx);
        }
        if even_index.is_some() && odd_index.is_some() {
            break;
        }
    }

    // unwrap is safe because of problem assumptions
    (even_index.unwrap(), odd_index.unwrap())
}